if (!function_exists('icons8')) {
    /**
     * Ikon Icons8 lewat hotlink CDN resmi mereka (img.icons8.com) — dipakai untuk kartu KPI
     * dashboard (gaya "color") dan empty state (gaya "3d-fluency"). Hotlink lewat CDN ini
     * gratis tanpa API key/login, lihat https://icons8.com/icons — bukan aset yang di-download
     * & disimpan sendiri, jadi selalu butuh koneksi internet saat halaman dibuka.
     */
    function icons8(string $name, string $style = 'color', int $size = 48): string
    {
        return "https://img.icons8.com/{$style}/{$size}/{$name}.png";
    }
}
